(async()=>{
  const blob = await fetch('/tmp_ai_test.png?v=2').then(r=>r.blob());
  const dataUrl = await new Promise(res=>{const fr=new FileReader(); fr.onload=()=>res(fr.result); fr.readAsDataURL(blob);});
  window.Cutter.loadFromDataURL(dataUrl, 'ai_test');
  await new Promise(r=>setTimeout(r,1800));
  return '导入完成 parts='+window.CutterEngine.S.parts.length+' size='+window.CutterEngine.S.w+'x'+window.CutterEngine.S.h;
})()
